"""Conteúdo editorial CC-13 — Código Civil, arts. 1.938 a 2.046."""
def row(diz,significa,exemplo,atencao,termo,definicao):
    return {"target":None,"o_que_diz":diz,"o_que_significa":significa,"exemplo_pratico":exemplo,"atencao":atencao,"palavras_dificeis":[{"termo":termo,"explicacao":definicao}]}

ROWS = {
"1938":row("O legado onerado segue, para o legatário, o regime das doações com encargo.","Quem recebe deve cumprir a obrigação associada, observadas as regras aplicáveis às liberalidades modais.","Testamento entrega imóvel ao sobrinho com dever de conservar biblioteca; aplicam-se as consequências do encargo.","Descumprimento e eventual resolução dependem do encargo e das regras remetidas, não de simples insatisfação do herdeiro.","Encargo","obrigação imposta ao beneficiário de uma liberalidade"),
"1939":row("O legado perde eficácia nas hipóteses legais de transformação, alienação, perda da coisa, exclusão ou morte prévia do legatário.","A disposição deixa de produzir resultado quando seu objeto ou beneficiário já não pode subsistir como previsto.","O testador vende metade do bem legado; a caducidade alcança somente a parte alienada.","Perecimento ou evicção só produzem o efeito indicado quando não houver culpa de quem devia cumprir o legado.","Caducidade","perda de eficácia por fato posterior previsto em lei"),
"1940":row("No legado alternativo, a perda de algumas opções preserva as restantes; perda parcial mantém o remanescente.","A impossibilidade limitada não extingue toda a liberalidade quando ainda existe objeto elegível.","Entre três obras alternativamente legadas, uma perece e o legatário recebe uma das duas restantes.","A regra pressupõe verdadeira alternatividade; a escolha e a imputação da perda seguem o título e a lei.","Legado alternativo","liberalidade cumprível com um entre vários objetos"),
"1941":row("A quota do herdeiro testamentário conjunto sem fração definida acresce às demais se ele não puder ou não quiser suceder, salvo substituto.","O chamamento coletivo absorve a vaga antes de ela retornar à sucessão legítima.","Três amigos são chamados conjuntamente sem percentuais; a renúncia de um aumenta a parte dos outros.","Quinhões determinados ou substituição prevista podem afastar o acréscimo.","Direito de acrescer","aumento da parcela dos chamados conjuntamente"),
"1942":row("Co-legatários têm acréscimo quando recebem juntos coisa única e certa ou objeto cuja divisão causaria desvalorização.","A unidade econômica do legado justifica concentrar a quota vaga nos demais beneficiários conjuntos.","Dois legatários recebem coleção indivisível; faltando um, o outro absorve a parcela.","Nomeação separada e objeto divisível podem conduzir a solução diversa.","Co-legatário","pessoa que compartilha o mesmo legado com outra"),
"1943":row("Morte prévia, renúncia, exclusão ou falha da condição fazem a quota acrescer aos conjuntos, salvo substituição; os encargos acompanham a parcela.","O beneficiário do acréscimo recebe também as limitações ligadas ao quinhão vago.","Legatário renuncia a quota onerada; o co-legatário a recebe com o dever imposto pelo testador.","Não se pode considerar apenas a vantagem e ignorar obrigações vinculadas.","Quinhão vago","parcela sem sucessor apto ou disposto a recebê-la"),
"1944":row("Sem direito de acrescer, a quota hereditária vaga vai aos sucessores legítimos; no legado, recai sobre quem devia satisfazê-lo conforme a regra legal.","A lei define destinatário residual quando a conjunção testamentária não absorve a vaga.","Legatário falta sem acréscimo; o encargo econômico retorna ao herdeiro responsável pelo legado.","A solução muda conforme se trate de instituição de herdeiro ou de legado.","Sucessor legítimo","herdeiro chamado pela ordem estabelecida em lei"),
"1945":row("O acréscimo não pode ser recusado separadamente da parcela original, salvo encargo especial; nessa exceção, reverte ao favorecido pelo encargo.","A unidade da atribuição impede escolha oportunista, mas protege contra obrigação especial não desejada.","Herdeiro aceita sua quota, mas rejeita acréscimo com dever específico em favor de terceiro.","Só encargo especial autoriza repúdio autônomo; ônus ordinários não bastam.","Repúdio","recusa juridicamente manifestada de uma atribuição"),
"1946":row("No usufruto conjunto, a parte do beneficiário faltante acresce aos demais; sem conjunção ou com frações certas, consolida-se no proprietário.","O destino da parcela depende de usufruto comum ou de quotas individualizadas.","Dois usufrutuários recebem o todo conjuntamente; falecendo um, o outro continua sobre a totalidade.","A consolidação extingue apenas a fração sem usufrutuário e exige examinar como o testamento distribuiu o direito.","Consolidação","reunião do usufruto e da propriedade na mesma titularidade"),
"1947":row("O testador pode indicar substituto para herdeiro ou legatário que não queira ou não possa receber, presumindo-se ambas as hipóteses.","A substituição vulgar evita que a atribuição fique vaga quando o primeiro chamado falha.","Filho é instituído e, se renunciar ou morrer antes, sobrinha o substitui.","A vontade expressa pode limitar a substituição a uma das situações.","Substituto","beneficiário chamado em lugar do primeiro nomeado"),
"1948":row("É possível substituir várias pessoas por uma, uma por várias e estabelecer substituição recíproca.","O testador dispõe de flexibilidade para organizar chamadas sucessivas dentro da lei.","Dois legatários são substituídos por uma fundação se nenhum puder receber.","A estrutura não pode violar legítima, capacidade sucessória ou limites de substituições.","Substituição recíproca","chamamento mútuo dos beneficiários para ocupar quota vaga"),
"1949":row("O substituto assume condição ou encargo do substituído, salvo intenção diferente ou incompatibilidade decorrente da natureza da obrigação.","A substituição normalmente preserva o conteúdo completo da atribuição.","Substituto recebe imóvel com o mesmo dever de manutenção imposto ao primeiro legatário.","Encargo personalíssimo pode não ser transferível.","Personalíssimo","ligado às qualidades específicas de determinada pessoa"),
"1950":row("Na substituição recíproca, mantêm-se as proporções originais; pessoa nova incluída na substituição divide igualmente a quota vaga.","A regra preserva o equilíbrio inicial e define rateio quando surge substituto sem quota anterior.","Herdeiros com 70% e 30% substituem-se nessa proporção; terceiro incluído altera o rateio da vaga para partes iguais.","É preciso distinguir participantes originais e pessoa acrescentada à segunda disposição.","Proporção testamentária","relação entre os quinhões fixados pelo testador"),
"1951":row("No fideicomisso, o fiduciário recebe primeiro e seu direito se resolve para transmissão posterior ao fideicomissário.","A propriedade é temporária e subordinada à morte, termo ou condição indicada pelo testador.","Bem passa ao filho e, quando ele morrer, ao neto indicado.","O instituto tem limites próprios e não autoriza cadeias sucessivas indefinidas.","Fideicomisso","substituição testamentária com titularidade sucessiva"),
"1952":row("O fideicomisso favorece apenas pessoa ainda não concebida na abertura da sucessão; se já nasceu, recebe a propriedade e o fiduciário fica com usufruto.","A existência do segundo beneficiário no momento da morte altera a natureza dos direitos.","Neto já nascido torna-se proprietário, enquanto o primeiro chamado conserva usufruto.","A concepção e o nascimento são avaliados na abertura da sucessão.","Fideicomissário","beneficiário final do fideicomisso"),
"1953":row("O fiduciário possui propriedade resolúvel, deve inventariar os bens e pode ter de prestar garantia de restituição.","Ele administra como proprietário temporário, preservando o patrimônio para o beneficiário final.","Fideicomissário exige caução diante do risco de dissipação dos bens.","A titularidade não permite frustrar o evento resolutório.","Propriedade resolúvel","domínio destinado a terminar com evento previsto"),
"1954":row("Se o fiduciário renuncia, o fideicomissário pode aceitar diretamente, salvo disposição testamentária contrária.","A recusa do titular intermediário não elimina necessariamente a liberalidade final.","Fiduciário rejeita a herança e o beneficiário futuro manifesta aceitação.","Deve-se conferir se o testador estabeleceu solução diferente.","Deferimento","atribuição legal do poder de aceitar"),
"1955":row("A renúncia do fideicomissário faz caducar o fideicomisso e consolida o domínio do fiduciário, salvo disposição diversa.","Sem beneficiário final, desaparece normalmente a limitação resolutória.","Fideicomissário renuncia e o fiduciário permanece proprietário pleno.","A vontade válida do testador pode prever outro destino.","Domínio pleno","propriedade sem a limitação resolutória do fideicomisso"),
"1956":row("O fideicomissário que aceita aproveita também os acréscimos posteriormente recebidos pelo fiduciário.","A atribuição final acompanha a ampliação do quinhão intermediário.","Quota acresce ao fiduciário durante sua titularidade e integra a futura transmissão.","O acréscimo precisa pertencer à herança ou legado gravado.","Acréscimo superveniente","parcela incorporada ao quinhão depois da abertura"),
"1957":row("Quando chega sua vez de suceder, o fideicomissário responde pelos encargos hereditários ainda pendentes.","A transmissão final inclui obrigações remanescentes ligadas ao patrimônio.","Ao receber os bens, paga dívida hereditária que ainda não havia sido quitada.","A responsabilidade observa os limites do patrimônio transmitido e o encargo efetivamente subsistente.","Encargo hereditário","obrigação vinculada à herança recebida"),
"1958":row("Morte do fideicomissário antes do fiduciário ou do evento resolutório extingue o fideicomisso e consolida a propriedade intermediária.","A falta do beneficiário final elimina a futura transferência prevista.","Fideicomissário falece antes do termo; o fiduciário torna-se proprietário definitivo.","Disposição testamentária válida em sentido diverso deve ser considerada.","Caducar","perder eficácia por acontecimento posterior"),
"1959":row("Fideicomissos que ultrapassem o segundo grau são nulos.","A lei impede sucessões encadeadas além do fiduciário e do fideicomissário permitidos.","Testamento tenta impor terceiro beneficiário sucessivo; o excesso não vale.","A nulidade alcança a cadeia proibida, conforme a preservação prevista no artigo seguinte.","Segundo grau","limite legal da substituição fideicomissária"),
"1960":row("A substituição fideicomissária ilegal é afastada sem invalidar a instituição principal, que permanece livre do encargo resolutório.","Preserva-se a atribuição válida retirando apenas a limitação proibida.","Cadeia excessiva é anulada e o primeiro beneficiário recebe sem aquela resolução.","Outros vícios autônomos da instituição ainda podem afetá-la.","Conservação do negócio","manutenção da parte válida apesar da nulidade parcial"),
"1961":row("Herdeiros necessários podem ser deserdados nas mesmas hipóteses que autorizam exclusão por indignidade.","A deserdação retira a legítima quando causa legal é declarada e provada.","Testador deserda descendente por fato que configura indignidade.","Deserdação não decorre de mera vontade: exige testamento, causa legal e prova.","Deserdação","privação testamentária da legítima por causa legal"),
"1962":row("Ofensa física, injúria grave, relação ilícita com padrasto ou madrasta e desamparo grave podem fundamentar deserdação de descendente.","São causas adicionais às de indignidade, interpretadas estritamente.","Filho abandona ascendente gravemente enfermo e é deserdado com indicação dessa causa.","A gravidade e os fatos precisam ser demonstrados; desavença comum não basta.","Injúria grave","ofensa relevante à dignidade da pessoa"),
"1963":row("Descendente pode deserdar ascendente por ofensa física, injúria grave, relações ilícitas familiares ou desamparo em situação protegida.","A lei enumera causas específicas além da indignidade.","Filho testa e deserda pai que o desamparou durante grave enfermidade.","A causa deve corresponder ao rol legal e ser provada.","Ascendente","antepassado na linha reta, como pai ou avô"),
"1964":row("A deserdação exige que o testamento declare expressamente a causa.","Não basta excluir genericamente o herdeiro necessário ou revelar ressentimento.","Testamento identifica o desamparo grave que fundamenta a deserdação.","Causa omitida ou diversa da provada impede o efeito pretendido.","Causa expressa","fundamento legal identificado no testamento"),
"1965":row("Quem se beneficia da deserdação deve provar a causa, em até quatro anos contados da abertura do testamento.","O ônus e o prazo recaem sobre o interessado em manter a exclusão.","Herdeiro instituído ajuíza ação e demonstra a ofensa alegada pelo testador.","O termo legal é a abertura do testamento, não necessariamente a data do óbito.","Ônus da prova","dever processual de demonstrar fato alegado"),
"1966":row("Se o testador dispõe apenas de parte da quota disponível, o restante cabe aos herdeiros legítimos.","A ausência de disposição não amplia automaticamente os quinhões testamentários.","Testador usa metade da parte disponível; o saldo segue a sucessão legítima.","Primeiro se preserva a legítima e depois se apura o remanescente disponível.","Parte disponível","fração patrimonial que pode ser livremente destinada"),
"1967":row("Disposições testamentárias acima da parte disponível são reduzidas proporcionalmente, primeiro nas instituições e depois nos legados, salvo preferência prevista.","A redução protege a legítima sem invalidar todo o testamento.","Quotas instituídas são diminuídas e, se insuficiente, reduzem-se também legados.","Preferências expressas do testador valem dentro dos limites legais.","Redução testamentária","diminuição necessária para recompor a legítima"),
"1968":row("Legado imobiliário divisível é reduzido proporcionalmente; se indivisível, a solução varia conforme o excesso e pode envolver entrega do bem ou reposição em dinheiro.","A lei procura conciliar preservação do imóvel e recomposição da parte indisponível.","Excesso pequeno é pago em dinheiro pelo legatário, que conserva o prédio.","Avaliação, limite de um quarto e eventual legítima do próprio legatário são decisivos.","Reposição","pagamento que equaliza valores entre beneficiários"),
"1969":row("O testamento pode ser revogado por qualquer forma testamentária admitida.","A revogação não precisa repetir exatamente o tipo do testamento anterior.","Testamento público posterior revoga disposição de testamento cerrado.","O ato revogatório deve cumprir solenidades de uma forma testamentária válida.","Revogação","retirada voluntária de eficácia de disposição anterior"),
"1970":row("A revogação pode alcançar todo o testamento ou apenas parte; sem incompatibilidade, disposições anteriores restantes continuam.","Testamentos sucessivos convivem no que forem compatíveis.","Novo testamento altera um legado e mantém as demais cláusulas antigas.","É necessário comparar conteúdo e eventual cláusula revogatória expressa.","Revogação parcial","supressão de somente algumas disposições"),
"1971":row("A revogação subsiste mesmo se o beneficiário posterior não suceder, mas cai se o testamento revogatório for anulado por vício formal ou intrínseco.","Fracasso da nova atribuição não restaura automaticamente a antiga; invalidade do próprio ato revogador pode fazê-lo.","Herdeiro do segundo testamento renuncia, mas a revogação do primeiro permanece.","Caducidade da atribuição e invalidade do testamento revogatório são situações distintas.","Vício intrínseco","defeito interno, como incapacidade ou vontade viciada"),
"1972":row("Testamento cerrado aberto ou destruído pelo testador, ou com seu consentimento, considera-se revogado.","A intervenção voluntária no invólucro demonstra desistência dessa forma secreta.","Testador rompe deliberadamente o documento cerrado guardado em casa.","Abertura acidental ou por terceiro sem consentimento exige apuração diferente.","Testamento cerrado","testamento sigiloso aprovado e lacrado perante tabelião"),
"1973":row("Descendente sucessível superveniente ou antes desconhecido rompe o testamento se sobreviver ao testador.","A lei presume que o testador teria disposto de modo diverso conhecendo esse herdeiro necessário.","Após testar sem filhos, a pessoa tem filho que lhe sobrevive; o testamento é rompido.","É preciso que o descendente seja sucessível e que o testador não o tivesse nem o conhecesse.","Rompimento","ineficácia legal do testamento por fato familiar superveniente"),
"1974":row("O testamento também se rompe quando foi feito ignorando a existência de outros herdeiros necessários.","O desconhecimento relevante altera a base familiar considerada pelo testador.","Testador desconhecia filho reconhecido posteriormente; examina-se o rompimento integral.","A regra não se aplica quando a existência era conhecida e a parte disponível foi conscientemente destinada.","Herdeiro necessário","sucessor protegido pela legítima"),
"1975":row("Não há rompimento se o testador, conhecendo os herdeiros necessários, dispõe somente da metade disponível sem contemplá-los nela.","A exclusão da parte livre é permitida quando a legítima permanece preservada.","Pai destina toda a quota disponível a terceiro e mantém intacta a legítima dos filhos.","O artigo não autoriza invadir a metade reservada.","Legítima","metade reservada aos herdeiros necessários"),
"1976":row("O testador pode nomear um ou mais testamenteiros para executar sua última vontade.","A função pode ser conjunta ou separada conforme a organização testamentária.","Dois testamenteiros recebem tarefas distintas para cumprir legados.","A nomeação não elimina competências do inventariante nem controles legais.","Testamenteiro","pessoa encarregada de executar o testamento"),
"1977":row("Sem cônjuge ou herdeiros necessários, o testador pode dar ao testamenteiro posse e administração; herdeiro pode pedir partilha garantindo meios aos legados.","A administração testamentária é instrumental e não impede indefinidamente a partilha.","Herdeiro oferece caução para cumprir legado e pede entrega imediata do acervo.","A faculdade depende da composição sucessória e da proteção efetiva dos legados.","Caução","garantia prestada para assegurar obrigação futura"),
"1978":row("Testamenteiro com posse e administração deve requerer inventário e executar o testamento.","Os poderes patrimoniais vêm acompanhados de deveres processuais e materiais.","Administrador testamentário abre inventário e providencia entrega de legados.","Omissão pode gerar responsabilidade e remoção.","Inventário","procedimento de apuração do acervo, dívidas e sucessores"),
"1979":row("Testamenteiro, interessado ou juiz de ofício pode exigir que o detentor apresente o testamento para registro.","O documento não pode ser ocultado de modo a frustrar a última vontade.","Herdeiro pede intimação de quem guarda o testamento cerrado.","Apresentação e registro não significam validação automática de todas as cláusulas.","Registro do testamento","formalização judicial de sua existência e conteúdo"),
"1980":row("O testamenteiro cumpre as disposições no prazo indicado e presta contas, mantendo responsabilidade enquanto a execução durar.","A função exige transparência sobre bens recebidos e despesas realizadas.","Testamenteiro apresenta relatório de pagamentos e comprovantes dos legados.","Prazo testamentário não afasta fiscalização nem responsabilidade por gestão irregular.","Prestação de contas","demonstração documentada da administração"),
"1981":row("Cabe ao testamenteiro defender a validade do testamento, com ou sem participação do inventariante e herdeiros.","Ele possui legitimação funcional para sustentar a última vontade.","Em ação anulatória, o testamenteiro apresenta defesa da regularidade formal.","Defender validade não autoriza ocultar vícios ou agir contra a lei.","Legitimação","aptidão jurídica para atuar em determinada demanda"),
"1982":row("O testamenteiro exerce ainda poderes atribuídos pelo testador, desde que dentro da lei.","A autonomia testamentária amplia funções, mas não supera normas obrigatórias.","Testador autoriza venda de bem para pagar legado, observados os requisitos legais.","Poder genérico não legitima violação da legítima ou dispensa de contas.","Atribuição testamentária","poder conferido pelo testamento"),
"1983":row("Sem prazo maior dado pelo testador, execução e contas devem ocorrer em 180 dias da aceitação, prorrogáveis por motivo suficiente.","A lei fixa duração padrão, permitindo extensão justificada.","Complexidade na venda de imóvel leva o juiz a prorrogar o prazo.","Prorrogação não é automática e requer razão concreta.","Testamentaria","encargo exercido pelo testamenteiro"),
"1984":row("Sem testamenteiro nomeado, a execução cabe ao cônjuge e, na falta, a herdeiro escolhido judicialmente.","A lei estabelece ordem subsidiária para não deixar o testamento sem executor.","Não havendo nomeação nem cônjuge, juiz designa um dos herdeiros.","A escolha deve observar aptidão e eventuais conflitos de interesses.","Executor testamentário","responsável por cumprir a última vontade"),
"1985":row("A testamentaria não passa aos herdeiros nem pode ser delegada, embora caiba mandatário com poderes especiais para representação.","O núcleo da função é pessoal; atos auxiliares específicos podem ser praticados por procurador.","Testamenteiro contrata advogado para representá-lo, mas continua responsável pelo encargo.","Mandato não transfere a titularidade da testamentaria.","Indelegável","função que não pode ser integralmente transferida"),
"1986":row("Com vários testamenteiros, um pode atuar na falta dos outros, e todos prestam contas solidariamente, salvo funções testamentárias separadas.","A solidariedade protege o acervo administrado conjuntamente.","Um testamenteiro executa medida urgente e os demais respondem pelas contas comuns.","Divisão expressa de funções limita a solidariedade ao âmbito efetivamente atribuído.","Responsabilidade solidária","possibilidade de cobrar de qualquer responsável o total devido"),
"1987":row("Testamenteiro que não seja herdeiro nem legatário recebe prêmio de 1% a 5% da herança líquida, se o testador não fixar, pago pela parte disponível.","A remuneração judicial considera valor e dificuldade do trabalho.","Juiz fixa 3% diante de execução complexa, sem atingir a legítima.","Percentual incide na herança líquida e não pode onerar a legítima quando há herdeiro necessário.","Vintena","prêmio remuneratório do testamenteiro"),
"1988":row("Herdeiro ou legatário também nomeado testamenteiro pode escolher o prêmio em lugar da herança ou legado.","A opção evita cumular benefícios quando a lei oferece alternativa.","Legatário prefere a remuneração calculada e renuncia ao legado.","A escolha exige comparar efeitos e não permite receber ambos com base neste artigo.","Opção","escolha jurídica entre benefícios incompatíveis"),
"1989":row("O prêmio perdido por remoção ou descumprimento retorna à herança.","Testamenteiro faltoso não conserva remuneração pelo encargo mal executado.","Removido por desvio, perde a vintena, que volta ao monte.","A perda do prêmio não exclui reparação por outros danos.","Reversão","retorno do valor ao patrimônio hereditário"),
"1990":row("Se toda a herança foi distribuída em legados, o testamenteiro desempenha também funções de inventariante.","A falta de herdeiro com quota residual concentra a administração no executor.","Testamento reparte todo o patrimônio em bens específicos; testamenteiro conduz o inventário.","A acumulação mantém deveres próprios de ambas as funções.","Inventariante","administrador e representante do espólio no inventário"),
"1991":row("O inventariante administra a herança entre seu compromisso e a homologação da partilha.","Nesse período, centraliza conservação, representação e gestão do espólio.","Inventariante paga despesas necessárias enquanto aguarda a partilha.","Atos de disposição podem depender de autorização e não confundem administração com propriedade.","Compromisso","ato formal de aceitação da função de inventariante"),
"1992":row("Herdeiro que oculta bem do inventário, da colação ou se recusa a restituí-lo perde o direito sobre o bem sonegado.","A pena patrimonial combate ocultação consciente do acervo comum.","Herdeiro esconde joia em seu poder e perde sua quota sobre ela.","A sonegação exige conduta juridicamente caracterizada; simples erro ou dúvida de titularidade deve ser apurado.","Sonegação","ocultação dolosa de bem da herança"),
"1993":row("Inventariante sonegador, além da perda patrimonial, é removido quando a ocultação ou negativa for provada.","A quebra de confiança impede sua permanência na administração.","Inventariante nega bem indicado e a prova confirma que o ocultou.","Remoção exige prova e procedimento adequado, não mera suspeita.","Remoção","afastamento judicial da função"),
"1994":row("A pena de sonegados depende de ação proposta por herdeiro ou credor da herança, e a sentença beneficia os demais interessados.","A sanção não é aplicada informalmente no inventário sem a demanda cabível.","Um credor ajuíza ação e o bem recuperado aproveita a todos.","Legitimidade ativa é a prevista no artigo e o resultado tem alcance coletivo sucessório.","Ação de sonegados","demanda destinada a apurar ocultação hereditária"),
"1995":row("Se o bem sonegado não puder ser devolvido, o responsável paga seu valor e perdas e danos.","A impossibilidade material converte a restituição em reparação equivalente.","Bem ocultado foi vendido; o sonegador repõe o valor e prejuízos adicionais.","A indenização não elimina automaticamente outras consequências da sonegação.","Perdas e danos","reparação dos prejuízos causados"),
"1996":row("A sonegação só pode ser arguida após inventariante ou herdeiro declarar encerrada a relação de bens e negar possuir outros.","A lei fixa momento em que a omissão se torna inequivocamente imputável.","Após declaração final do inventariante, aparece bem que ele conscientemente omitiu.","Antes desse marco, pode haver correção do inventário sem caracterização automática da pena.","Arguição","alegação formal de determinada questão"),
"1997":row("Antes da partilha, a herança paga dívidas; depois, cada herdeiro responde na proporção recebida, com reserva judicial possível e prazo de 30 dias para cobrança.","A responsabilidade desloca-se do monte para os quinhões sem superar o benefício hereditário.","Credor documentado obtém reserva de bem e ajuíza cobrança dentro do prazo.","Impugnação relevante, prova da dívida e limite da herança precisam ser considerados.","Reserva de bens","separação cautelar de patrimônio para possível pagamento"),
"1998":row("Despesas funerárias saem da herança; sufrágios religiosos só a obrigam quando ordenados em testamento ou codicilo.","O monte suporta funeral razoável, mas gastos espirituais exigem manifestação do falecido.","Espólio paga sepultamento, mas missa especial apenas se prevista.","Despesas devem ser relacionadas ao falecimento e compatíveis com o acervo.","Monte da herança","conjunto patrimonial antes da partilha"),
"1999":row("Na ação regressiva entre herdeiros, a parcela do insolvente é repartida proporcionalmente entre os demais.","O risco interno da insolvência é redistribuído segundo as participações hereditárias.","Herdeiro que pagou dívida cobra os outros; a parte de um insolvente é rateada.","O rateio ocorre na relação regressiva, não cria responsabilidade ilimitada além da herança.","Ação regressiva","cobrança contra coobrigados após pagamento"),
"2000":row("Legatários e credores hereditários podem separar o patrimônio do falecido do patrimônio do herdeiro e preferem aos credores pessoais deste.","A separação protege quem confiou no acervo hereditário contra dívidas particulares do sucessor.","Credor do espólio pede discriminação e recebe antes do credor pessoal do herdeiro.","A preferência recai sobre patrimônio hereditário identificado, não sobre qualquer bem do herdeiro.","Separação patrimonial","distinção de massas de bens para pagamento de credores"),
"2001":row("Dívida do herdeiro para com o espólio é dividida entre todos, salvo maioria aceitar imputação integral ao quinhão do devedor.","O crédito hereditário integra o acervo, mas pode ser compensado concentradamente.","Herdeiro deve ao falecido e a maioria desconta tudo de sua quota.","A deliberação deve preservar os demais quinhões e a correta avaliação do débito.","Imputação no quinhão","desconto de obrigação na parcela hereditária"),
"2002":row("Descendentes concorrentes devem colacionar doações recebidas do ascendente para igualar legítimas, sob pena de sonegação.","Adiantamentos recebidos em vida entram no cálculo da parcela reservada.","Um filho recebeu imóvel e informa seu valor na sucessão do pai.","Colação não significa necessariamente devolver o bem; sua forma depende das regras seguintes.","Colação","conferência de doações para equalizar legítimas"),
"2003":row("A colação iguala legítimas de descendentes e cônjuge, inclusive quando o donatário já não possui o bem; falta de acervo pode exigir espécie ou valor histórico.","A alienação posterior não elimina o adiantamento recebido.","Filho vendeu bem doado e confere o valor da liberalidade na partilha.","O valor e a forma seguem os critérios legais, não o preço atual escolhido livremente.","Donatário","pessoa que recebeu doação"),
"2004":row("O valor colacionado é o atribuído na doação; sem valor, estima-se o da época, excluindo benfeitorias, rendimentos e riscos posteriores.","A equalização olha a liberalidade original, separando acréscimos produzidos pelo donatário.","Imóvel sem avaliação é estimado pelo valor que tinha quando doado.","Não se incorpora automaticamente valorização decorrente de melhoria paga pelo herdeiro.","Valor de colação","montante considerado para equalizar legítimas"),
"2005":row("Doação expressamente saída da parte disponível é dispensada da colação até o limite; há presunção para descendente que então não seria herdeiro necessário.","A dispensa respeita a liberdade do doador sem permitir invasão da legítima.","Avô doa a neto que não concorria à sucessão e imputa na parte disponível.","Excesso continua sujeito a redução, ainda que exista dispensa.","Dispensa de colação","determinação de que doação não seja conferida para igualação"),
"2006":row("O doador pode dispensar colação no testamento ou no próprio instrumento da doação.","A dispensa precisa constar de forma expressa em ato admitido.","Escritura declara que o bem sai da parte disponível.","Declaração posterior informal não substitui os meios legais.","Título de liberalidade","instrumento que formaliza a doação"),
"2007":row("Doações acima do que o doador podia dispor são reduzidas; apura-se o excesso na data da liberalidade e restitui-se em espécie ou dinheiro segundo regras legais.","A redução recompõe a legítima, começando pelas doações mais recentes quando houver várias.","Última doação excedente é reduzida até eliminar invasão da reserva.","Datas diferentes controlam valor, ordem de redução e conversão monetária.","Doação inoficiosa","liberalidade que excede a parte disponível"),
"2008":row("Quem renunciou ou foi excluído da herança ainda deve conferir doações para devolver eventual excesso da parte disponível.","A saída da sucessão não permite conservar liberalidade ofensiva à legítima.","Filho renuncia, mas repõe parcela da doação que ultrapassou a quota livre.","A conferência aqui visa redução do excesso, não atribuir-lhe herança.","Excesso disponível","valor que supera a parcela livre do patrimônio"),
"2009":row("Netos que sucedem por representação devem colacionar o que seus pais teriam de conferir, mesmo sem ter recebido esses bens.","A estirpe representada entra na igualdade com os adiantamentos feitos ao ascendente intermediário.","Neto representa pai falecido e computa doação antes feita ao pai.","Não se trata de afirmar que o neto recebeu a doação, mas de ajustar o quinhão da estirpe.","Estirpe","ramo familiar representado na sucessão"),
"2010":row("Gastos ordinários de criação, saúde, educação, vestuário, casamento e defesa penal do descendente menor não entram em colação.","Despesas familiares comuns não são tratadas como adiantamento de herança.","Mensalidades escolares pagas durante a infância não são conferidas.","Gastos extraordinários disfarçando doação exigem análise dos fatos.","Gasto ordinário","despesa normal de sustento e formação familiar"),
"2011":row("Doações remuneratórias por serviços prestados ao ascendente não são colacionadas.","A liberalidade que recompensa serviço não funciona como simples antecipação da legítima.","Pai doa valor ao filho pelos cuidados profissionais prestados.","É necessário caráter efetivamente remuneratório, e eventual excesso pode enfrentar outros controles.","Doação remuneratória","liberalidade em reconhecimento de serviço"),
"2012":row("Doação feita por ambos os cônjuges é conferida pela metade no inventário de cada um.","Cada patrimônio sucessório suporta a fração atribuível ao respectivo doador.","Imóvel doado conjuntamente é contabilizado 50% na sucessão de cada cônjuge.","Regime de bens e titularidade do objeto devem ser compatíveis com a divisão.","Conferência por metade","imputação igual da doação aos dois inventários"),
"2013":row("Herdeiro, cessionário ou credor pode requerer partilha apesar de proibição testamentária.","O testador não pode manter indefinidamente a indivisão contra os legitimados.","Credor do herdeiro pede partilha para alcançar o quinhão.","A faculdade observa procedimento e direitos dos demais interessados.","Cessionário","quem recebeu direitos hereditários por cessão"),
"2014":row("O testador pode distribuir bens entre quinhões, desde que os valores correspondam às quotas devidas.","A partilha testamentária orienta a composição material, mas não altera percentuais protegidos.","Testador atribui empresa a um filho e imóveis a outro com valores equivalentes.","Desigualdade de valores exige correção para respeitar legítimas e quotas.","Partilha testamentária","divisão patrimonial feita pelo testador"),
"2015":row("Herdeiros capazes podem realizar partilha amigável por escritura, termo judicial ou escrito particular homologado.","O consenso e a capacidade permitem formas menos litigiosas, observadas as formalidades.","Herdeiros adultos formalizam acordo em escritura pública.","Tributos, representação e requisitos processuais ou registrais continuam aplicáveis.","Partilha amigável","divisão consensual da herança"),
"2016":row("Divergência entre herdeiros ou incapacidade de algum deles torna a partilha judicial.","A intervenção judicial protege conflito e vulnerabilidade.","Herdeiro menor participa e a divisão é submetida ao juízo.","A existência de incapaz exige observar também regras processuais atuais.","Partilha judicial","divisão realizada sob controle do juízo"),
"2017":row("A partilha deve buscar máxima igualdade quanto a valor, natureza e qualidade dos bens.","Equivalência não é apenas matemática: considera utilidade e composição dos quinhões.","Dois herdeiros recebem conjuntos equilibrados de imóveis e ativos líquidos.","Diferenças inevitáveis podem exigir reposições financeiras.","Igualdade qualitativa","equilíbrio também quanto ao tipo e utilidade dos bens"),
"2018":row("Ascendente pode partilhar em vida ou por última vontade, desde que preserve a legítima.","A divisão antecipada é válida dentro da parcela reservada a herdeiros necessários.","Mãe distribui imóveis entre filhos em escritura, mantendo quinhões legítimos.","O ato pode envolver doação e seus requisitos, além da proteção da legítima.","Partilha em vida","divisão patrimonial feita pelo ascendente antes da morte"),
"2019":row("Bem indivisível que não caiba em um quinhão é vendido e o preço dividido, salvo adjudicação consensual ou requerida com reposição e licitação.","A lei evita fracionamento antieconômico e oferece preferência prática aos sucessores.","Um herdeiro fica com fazenda indivisível e paga diferenças após avaliação.","Havendo vários interessados, aplica-se licitação; avaliação deve ser atual.","Adjudicação","atribuição integral do bem a determinado interessado"),
"2020":row("Quem possui bens hereditários deve entregar frutos desde a abertura, recebe despesas necessárias e úteis e responde por dano culposo ou doloso.","A prestação de contas equilibra benefícios, gastos e prejuízos durante a indivisão.","Herdeiro entrega aluguéis recebidos e é reembolsado por reparo essencial.","Despesa voluptuária não se equipara automaticamente a necessária ou útil.","Frutos","rendimentos produzidos pelo bem"),
"2021":row("Bens remotos, litigiosos ou de liquidação difícil podem ficar para sobrepartilha, enquanto os demais são divididos.","A complexidade parcial não precisa atrasar toda a sucessão.","Ações judiciais ficam reservadas e imóveis livres são partilhados.","A guarda, administração e consentimento majoritário devem ser formalizados.","Sobrepartilha","partilha posterior de bens não divididos inicialmente"),
"2022":row("Bens sonegados ou descobertos após a partilha são submetidos a sobrepartilha.","O encerramento inicial não deixa patrimônio posterior sem divisão.","Conta desconhecida é localizada anos depois e repartida em procedimento complementar.","A sobrepartilha não apaga penalidades por eventual sonegação.","Bem superveniente","ativo conhecido somente depois da partilha"),
"2023":row("Após o julgamento da partilha, cada herdeiro passa a ter direito exclusivo sobre os bens do seu quinhão.","A comunhão hereditária é substituída por titularidades individualizadas.","Homologada a divisão, cada sucessor registra os imóveis que recebeu.","Formalidades registrais podem ser necessárias para eficácia perante terceiros.","Quinhão","parcela individual da herança"),
"2024":row("Co-herdeiros devem indenizar reciprocamente aquele que perder bem partilhado por evicção.","O risco de defeito jurídico anterior à divisão é repartido entre todos.","Herdeiro perde imóvel para verdadeiro proprietário e cobra compensação dos demais.","A obrigação pode cessar nas hipóteses do artigo seguinte.","Evicção","perda do bem por direito anterior reconhecido a terceiro"),
"2025":row("A garantia por evicção cessa por convenção contrária, culpa do evicto ou fato posterior à partilha.","A solidariedade sucessória não cobre riscos assumidos ou causados pelo próprio prejudicado.","Herdeiro perde o bem por ato praticado depois da partilha e não cobra os demais.","A cláusula de exclusão e a culpa precisam ser válidas e demonstradas.","Evicto","pessoa que sofreu a perda por evicção"),
"2026":row("A indenização por evicção é proporcional às quotas; insolvência de co-herdeiro é redistribuída, descontada a parcela do próprio indenizado.","O prejuízo comum é rateado sem fazer o evicto pagar a si mesmo.","Um co-herdeiro insolvente tem sua parte repartida entre os solventes.","Cálculo depende das quotas hereditárias originais.","Rateio proporcional","divisão segundo a participação de cada herdeiro"),
"2027":row("Partilha com vícios gerais dos negócios jurídicos é anulável, e a pretensão deve ser exercida em um ano.","Erro, dolo ou outros defeitos podem desconstituir a divisão dentro do prazo legal.","Herdeiro enganado ajuíza anulação antes de completar um ano.","É preciso distinguir partilha anulável de hipóteses de nulidade ou rescisão regidas por normas próprias.","Anulabilidade","invalidade que depende de iniciativa e prazo"),
"2028":row("Prazo reduzido pelo Código novo continua seguindo a lei anterior se, na entrada em vigor, já havia transcorrido mais da metade do prazo antigo.","A transição protege situações temporais avançadas sob a legislação revogada.","Prescrição antiga estava além da metade em 2003 e conserva o prazo anterior.","Regra é transitória e exige comparar datas e durações concretas.","Direito intertemporal","regras que definem qual lei rege fatos no tempo"),
"2029":row("Durante os dois primeiros anos de vigência, determinados prazos de usucapião tiveram acréscimo temporário de dois anos.","A norma criou ajuste transitório já exaurido para posses vindas do Código anterior.","Posse examinada em 2004 recebeu o acréscimo então previsto.","Não se adicionam dois anos a usucapiões atuais sem vínculo com aquela transição.","Acréscimo transitório","extensão temporária aplicável em período histórico delimitado"),
"2030":row("O acréscimo transitório anterior também alcançou a hipótese especial do art. 1.228, § 4º.","A extensão temporal foi aplicada a essa modalidade coletiva durante a transição.","Demanda possessória do período inicial considerou os dois anos adicionais.","O artigo depende do 2.029 e não cria prazo permanente autônomo.","Remissão","referência normativa a outro dispositivo"),
"2031":row("Entidades e empresários anteriores tiveram prazo até 11 de janeiro de 2007 para adaptação, excetuados organizações religiosas e partidos.","Foi regra de transição institucional com prazo já encerrado.","Sociedade antiga alterou contrato até a data histórica indicada.","Não se apresenta 2007 como prazo ainda aberto; situações atuais seguem o regime vigente.","Adaptação societária","adequação de estrutura antiga à lei nova"),
"2032":row("Fundações criadas sob lei anterior passaram a seguir o Código quanto ao funcionamento, mesmo com finalidades antes admitidas.","A norma separa constituição histórica e disciplina operacional posterior.","Fundação antiga mantém origem, mas presta contas segundo o novo regime.","Leis especiais e alterações posteriores também devem ser consideradas.","Funcionamento","regras aplicáveis à atuação continuada da entidade"),
"2033":row("Alterações estruturais de pessoas jurídicas seguem imediatamente o Código, salvo lei especial.","Transformação, incorporação, cisão e fusão posteriores submetem-se à disciplina nova.","Sociedade antiga realiza fusão depois de 2003 e observa o Código atual.","A ressalva de lei especial pode deslocar a disciplina geral.","Cisão","divisão patrimonial de pessoa jurídica"),
"2034":row("Dissolução ou liquidação iniciada antes da vigência do Código continua regida pela lei anterior.","Preserva-se o regime do procedimento já em curso.","Liquidação iniciada em 2002 segue as normas então aplicáveis.","O marco é o início efetivo antes da vigência, não a mera constituição antiga da entidade.","Ultratividade","aplicação continuada de lei antiga a situação específica"),
"2035":row("Validade de atos anteriores segue a lei antiga; efeitos posteriores seguem o Código novo, salvo execução prevista, sempre subordinada à ordem pública.","A transição preserva formação válida, mas submete efeitos futuros a normas imperativas atuais.","Contrato de 2001 permanece válido, porém efeitos de 2004 observam função social.","A regra não autoriza retroatividade irrestrita nem convenção contra ordem pública.","Ordem pública","normas imperativas indisponíveis pelas partes"),
"2036":row("Locação urbana abrangida por lei especial continua regida por ela.","O Código não substituiu o regime locatício específico.","Contrato residencial segue a Lei do Inquilinato.","É preciso verificar se a locação está efetivamente no âmbito da lei especial.","Lei especial","norma dirigida a matéria específica que prevalece sobre a geral"),
"2037":row("Normas comerciais anteriores não revogadas continuam aplicáveis a empresários e sociedades, salvo disposição contrária.","A transição conserva disciplina compatível até substituição normativa.","Regra mercantil antiga ainda válida complementa matéria empresarial.","Deve-se confirmar vigência e compatibilidade, não presumir sobrevivência de toda norma antiga.","Direito mercantil","conjunto de regras históricas da atividade comercial"),
"2038":row("Novas enfiteuses são proibidas; as antigas seguem o Código de 1916 até extinção, com restrições a laudêmio sobre melhorias e subenfiteuse; terrenos de marinha têm lei especial.","O instituto sobrevive apenas transitoriamente em vínculos preexistentes.","Aforamento antigo continua, mas não cobra laudêmio sobre construção.","Não se confunde enfiteuse civil extinta com regime especial de terrenos de marinha.","Enfiteuse","direito real antigo com domínio útil e pagamento ao senhorio"),
"2039":row("Casamentos celebrados sob o Código de 1916 mantêm o regime de bens então estabelecido.","A lei do momento da celebração preserva a disciplina patrimonial matrimonial.","Casal casado em 1990 conserva o regime definido naquela época.","Atos posteriores e eventual alteração judicial do regime exigem análise própria.","Regime de bens","conjunto de regras patrimoniais do casamento"),
"2040":row("Hipoteca legal antiga de tutor ou curador pode ser cancelada conforme a garantia substitutiva prevista no Código atual.","A norma oferece transição para liberar gravame constituído no regime anterior.","Curador demonstra condições legais e pede cancelamento do registro histórico.","Cancelamento depende do procedimento e da proteção do incapaz.","Hipoteca legal","garantia imobiliária imposta diretamente pela lei"),
"2041":row("A ordem sucessória do Código novo não rege sucessões abertas antes de sua vigência; aplica-se a lei anterior.","A lei da data do óbito determina a vocação hereditária.","Falecimento em 2002 é partilhado segundo o Código de 1916.","Inventário posterior não muda a lei sucessória se a abertura ocorreu antes.","Abertura da sucessão","momento da morte em que a herança se transmite"),
"2042":row("Restrição testamentária à legítima em sucessão aberta no primeiro ano do Código exigia aditamento com justa causa, sob pena de desaparecer.","Foi transição anual específica para testamentos antigos.","Testador aditou em 2003 cláusula restritiva e declarou sua causa.","O prazo histórico está exaurido e não funciona como regra permanente.","Aditamento","acréscimo formal a ato anterior"),
"2043":row("Normas processuais, administrativas ou penais de leis parcialmente incorporadas continuam até disciplina substitutiva.","A incorporação civil não eliminou automaticamente regras de outra natureza.","Procedimento especial antigo permanece enquanto não houver norma nova.","É indispensável verificar se houve disciplina posterior e se a regra não foi revogada.","Natureza processual","regra sobre procedimento e exercício em juízo"),
"2044":row("O Código começou a vigorar um ano depois de publicado.","A vacância permitiu preparação antes da eficácia geral em 11 de janeiro de 2003.","Ato de fevereiro de 2003 já se submete ao novo Código, ressalvadas transições.","Publicação e vigência são datas distintas.","Vacatio legis","intervalo entre publicação e entrada em vigor"),
"2045":row("O Código revogou o Código Civil de 1916 e a Parte Primeira do Código Comercial de 1850.","Houve revogação legislativa expressa, preservadas regras transitórias e partes não alcançadas.","Relação civil posterior deixa de usar o Código de 1916 como regime geral.","Revogação não apaga efeitos passados nem toda a legislação comercial.","Revogação expressa","retirada de vigência declarada diretamente pela lei"),
"2046":row("Referências legislativas aos códigos revogados passam a apontar para disposições correspondentes do Código atual.","A conversão evita que remissões antigas fiquem sem objeto.","Lei antiga menciona artigo do Código de 1916 e intérprete busca equivalente vigente.","Correspondência exige análise material; números de artigos não são automaticamente equivalentes.","Remissão legislativa","referência de uma norma a outra"),
}

_B={"1939","1943","1944","1945","1946","1950","1952","1953","1958","1960","1961","1962","1963","1965","1967","1968","1971","1973","1974","1977","1983","1984","1986","1987","1992","1994","1996","1997","2000","2002","2003","2004","2005","2007","2008","2009","2014","2016","2018","2019","2020","2021","2024","2026","2027","2028","2029","2030","2031","2032","2033","2034","2035","2037","2038","2039","2040","2041","2042","2043","2045","2046"}
AUDIT={a:{"classification":"B" if a in _B else "A","rationale":"Revisão individual confirmou o alcance e a ressalva: "+r["atencao"]} for a,r in ROWS.items()}
